import 'package:flutter/material.dart';import '../models/commitment.dart';import '../services/storage_service.dart';import '../services/notification_service.dart';class TodayScreen extends StatefulWidget{const TodayScreen({super.key});@override State<TodayScreen> createState()=>_S();}class _S extends State<TodayScreen>{@override Widget build(BuildContext c){final all=StorageService.commitments();final n=DateTime.now();final d=DateTime(n.year,n.month,n.day);final o=all.where((x)=>x.status=='pending'&&x.dueDate.isBefore(d)).toList();final t=all.where((x)=>x.status=='pending'&&x.dueDate.year==d.year&&x.dueDate.month==d.month&&x.dueDate.day==d.day).toList();final f=all.where((x)=>x.status=='pending'&&x.dueDate.isAfter(d)).toList();Widget sec(String title,List<Commitment> xs){if(xs.isEmpty)return const SizedBox();return Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Padding(padding:const EdgeInsets.all(12),child:Text(title,style:const TextStyle(fontWeight:FontWeight.bold))),...xs.map((x)=>Card(child:ListTile(title:Text('${x.person}${x.amount==null?'':' - ${x.amount!.toStringAsFixed(0)} ج'}'),subtitle:Text(x.textOriginal),trailing:IconButton(icon:const Icon(Icons.check_circle_outline),onPressed:()async{x.status='done';await StorageService.saveCommitment(x);await NotificationService.cancel(x.id);setState((){});}))))]);}return Scaffold(appBar:AppBar(title:const Text('ماذا عليك اليوم؟')),body:ListView(children:[sec('🔴 متأخر',o),sec('🟡 اليوم',t),sec('🟢 قادم',f),if(o.isEmpty&&t.isEmpty&&f.isEmpty)const Padding(padding:EdgeInsets.all(40),child:Center(child:Text('لا توجد التزامات. ابدأ من الشات.')))]));}}
